import static org.junit.Assert.assertEquals;

public class LocalDate_fromCalendarFields_TriageGen1Test {



    @Test
    public void testFromCalendarFields_BC_Year() {
        // Test with Gregorian Calendar BC era
        // The logic: (era == AD ? yearOfEra : 1 - yearOfEra)
        // If era is BC, year 1 becomes 1 - 1 = 0. Year 2 becomes 1 - 2 = -1.
        Calendar calendar = new GregorianCalendar();
        calendar.set(1, Calendar.JANUARY, 1);
        calendar.set(Calendar.ERA, GregorianCalendar.BC);

        LocalDate expected = new LocalDate(0, 1, 1);
        LocalDate actual = LocalDate.fromCalendarFields(calendar);

        assertEquals("Should correctly convert BC year using (1 - yearOfEra) logic", expected, actual);
    }




}

