    public void testFromCalendarFields_BC_Year_Negative() {
        // Test with a higher BC year
        Calendar calendar = new GregorianCalendar();
        calendar.set(500, Calendar.DECEMBER, 31);
        calendar.set(Calendar.ERA, GregorianCalendar.BC);

        // 1 - 500 = -499
